all.css:
.star-container {
  position: absolute;
  inset: 0;
  background: #292957;
  background: radial-gradient(circle,rgba(41, 41, 87, 1) 25%, rgba(4, 11, 13, 1) 100%);
  overflow: hidden;
}

/* DUST: static haze, no twinkle. Tiles pushed past window width so the repeat doesn't read. */
.star-container::before,
.star-container::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.star-container::before {
  background-image:
    radial-gradient(circle, rgba(255,255,255,0.85) 0.8px, transparent 1.8px),
    radial-gradient(circle, rgba(255,255,255,0.65) 0.8px, transparent 1.8px),
    radial-gradient(circle, rgba(255,255,255,0.75) 0.8px, transparent 1.8px),
    radial-gradient(circle, rgba(255,255,255,0.55) 0.8px, transparent 1.8px),
    radial-gradient(circle, rgba(255,255,255,0.80) 0.8px, transparent 1.8px),
    radial-gradient(circle, rgba(255,255,255,0.60) 0.8px, transparent 1.8px),
    radial-gradient(circle, rgba(255,255,255,0.70) 0.8px, transparent 1.8px),
    radial-gradient(circle, rgba(255,255,255,0.50) 0.8px, transparent 1.8px);
  background-position: 29px 47px, 213px 288px, 388px 129px, 97px 401px,
                       472px 334px, 266px 533px, 557px 478px, 401px 61px;
  background-size: 590px 590px;
  opacity: 0.9;
}

.star-container::after {
  background-image:
    radial-gradient(circle, rgba(255,255,255,0.70) 0.8px, transparent 1.8px),
    radial-gradient(circle, rgba(255,255,255,0.58) 0.8px, transparent 1.8px),
    radial-gradient(circle, rgba(255,255,255,0.80) 0.8px, transparent 1.8px),
    radial-gradient(circle, rgba(255,255,255,0.52) 0.8px, transparent 1.8px),
    radial-gradient(circle, rgba(255,255,255,0.66) 0.8px, transparent 1.8px),
    radial-gradient(circle, rgba(255,255,255,0.60) 0.8px, transparent 1.8px);
  background-position: 71px 197px, 293px 38px, 424px 371px,
                       182px 452px, 508px 144px, 63px 319px;
  background-size: 523px 523px; /* coprime-ish with ::before so the two grids don't lock up */
  opacity: 0.8;
}

/* Shared: the only animated property is opacity, so each of these stays on the compositor and the
   fade never touches the main thread. --tile is what makes nine elements look like nine different
   star fields from three dot patterns: same positions, different repeat period, different spacing. */
.stars {
  position: absolute;
  inset: 0;
  background-repeat: repeat;
  animation: twinkle var(--dur) ease-in-out var(--delay) infinite;
  will-change: opacity;
}

.stars.small {
  /* background-image and background-position unchanged */
  background-size:
    calc(var(--tile) * 1.00) calc(var(--tile) * 0.93),
    calc(var(--tile) * 0.83) calc(var(--tile) * 1.11),
    calc(var(--tile) * 1.07) calc(var(--tile) * 0.79),
    calc(var(--tile) * 0.91) calc(var(--tile) * 1.03),
    calc(var(--tile) * 0.76) calc(var(--tile) * 0.87),
    calc(var(--tile) * 1.13) calc(var(--tile) * 0.97),
    calc(var(--tile) * 0.87) calc(var(--tile) * 1.19),
    calc(var(--tile) * 0.97) calc(var(--tile) * 0.71),
    calc(var(--tile) * 1.19) calc(var(--tile) * 1.09),
    calc(var(--tile) * 0.71) calc(var(--tile) * 0.83),
    calc(var(--tile) * 1.03) calc(var(--tile) * 1.13),
    calc(var(--tile) * 0.79) calc(var(--tile) * 0.91);
}

.stars.medium {
  background-size:
    calc(var(--tile) * 1.00) calc(var(--tile) * 0.89),
    calc(var(--tile) * 0.81) calc(var(--tile) * 1.13),
    calc(var(--tile) * 1.11) calc(var(--tile) * 0.77),
    calc(var(--tile) * 0.93) calc(var(--tile) * 1.07),
    calc(var(--tile) * 0.74) calc(var(--tile) * 0.91),
    calc(var(--tile) * 1.17) calc(var(--tile) * 1.01),
    calc(var(--tile) * 0.89) calc(var(--tile) * 1.21),
    calc(var(--tile) * 1.03) calc(var(--tile) * 0.73);
}

.stars.large {
  background-size:
    calc(var(--tile) * 1.00) calc(var(--tile) * 0.87),
    calc(var(--tile) * 0.79) calc(var(--tile) * 1.09),
    calc(var(--tile) * 1.13) calc(var(--tile) * 0.76),
    calc(var(--tile) * 0.91) calc(var(--tile) * 1.17),
    calc(var(--tile) * 1.07) calc(var(--tile) * 0.97),
    calc(var(--tile) * 0.73) calc(var(--tile) * 0.83);
}

@keyframes twinkleSmall  { 0%, 100% { opacity: 0.65; } 50% { opacity: 1; } }
@keyframes twinkleMedium { 0%, 100% { opacity: 0.60; } 50% { opacity: 1; } }
@keyframes twinkleLarge  { 0%, 100% { opacity: 0.65; } 50% { opacity: 1; } }

@media (prefers-reduced-motion: reduce) {
  .stars { animation: none; opacity: 0.95; }
}
